```xml
// Ant build.xml (circa 2003) - everything is manual
<target name="compile">
    <mkdir dir="build/classes"/>
    <javac srcdir="src" destdir="build/classes"/>
</target>

// Maven pom.xml (circa 2006) - conventions handle compilation
<project>
    <dependencies>
        <dependency>
            <groupId>junit</groupId>
            <artifactId>junit</artifactId>
            <version>4.12</version>
        </dependency>
    </dependencies>
</project>

// Gradle build.gradle (circa 2015) - programmatic and concise
dependencies {
    testImplementation 'junit:junit:4.12'
}

// Modern Gradle with Kotlin DSL (2020+)
dependencies {
    testImplementation("org.junit.jupiter:junit-jupiter:5.10.0")
}
```

```java
// When you run: mvn clean package

// Step 1: clean lifecycle
// - Deletes target/ directory

// Step 2: default lifecycle phases execute in order:
public class OrderService {
    // Phase: validate - checks pom.xml structure
    // Phase: compile - javac compiles this to target/classes/

    public Order createOrder(String item) {
        return new Order(item);
    }
}

// Phase: test - runs this test class
class OrderServiceTest {
    @Test
    void shouldCreateOrder() {
        var service = new OrderService();
        var order = service.createOrder("Laptop");
        assertNotNull(order);
    }
}

// Phase: package - creates target/order-service-1.0.jar
// Phases install and deploy would copy/upload the JAR
```
